MAP
    NAME "SS_MAP_DREN_REJILLAS_CATASTRO"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_rejillas_catastro.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_DREN_REJILLAS_UBICACION"
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from rejillas_catastro using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        CLASS
            NAME "rejillas de catastro"
            STYLE
                COLOR 192 178 140
                OUTLINECOLOR 84 61 0
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP